class TestEnvInjection:
    """Validate env var parsing, coercion, and validation."""

    @pytest.mark.parametrize(
        "env_var,raw_value,expected",
        [
            ("QKD_SERVICE_HOST", "10.0.0.5", "10.0.0.5"),
            ("QKD_SERVICE_HOST", "qkd.internal", "qkd.internal"),
            ("QKD_LOG_LEVEL", "DEBUG", "DEBUG"),
            ("QKD_LOG_LEVEL", "warning", "WARNING"),  # case normalization
        ],
    )
    def test_string_coercion(self, fresh_config, monkeypatch, env_var, raw_value, expected):
        monkeypatch.setenv(env_var, raw_value)
        cfg = fresh_config()
        actual = getattr(cfg, self._attr_for_env(env_var))
        assert actual == expected

    @pytest.mark.parametrize(
        "env_var,raw_value,expected",
        [
            ("QKD_SERVICE_PORT", "9000", 9000),
            ("QKD_MAX_KEYS", "2048", 2048),
            ("QKD_ROTATION_INTERVAL", "7200", 7200),
            ("QKD_KEY_TTL", "172800", 172800),
            ("QKD_KYBER_PUBLIC_KEY_SIZE", "1568", 1568),
            ("QKD_KYBER_SECRET_KEY_SIZE", "3168", 3168),
            ("QKD_KYBER_CIPHERTEXT_SIZE", "1568", 1568),
        ],
    )
    def test_int_coercion(self, fresh_config, monkeypatch, env_var, raw_value, expected):
        monkeypatch.setenv(env_var, raw_value)
        cfg = fresh_config()
        actual = getattr(cfg, self._attr_for_env(env_var))
        assert actual == expected
        assert isinstance(actual, int)

    @pytest.mark.parametrize(
        "env_var,raw_value,expected",
        [
            ("FVE_ENABLED", "true", True),
            ("FVE_ENABLED", "1", True),
            ("FVE_ENABLED", "yes", True),
            ("FVE_ENABLED", "false", False),
            ("FVE_ENABLED", "0", False),
            ("FVE_ENABLED", "no", False),
            ("FVE_STRICT_MODE", "TRUE", True),
            ("FVE_STRICT_MODE", "False", False),
        ],
    )
    def test_bool_coercion(self, fresh_config, monkeypatch, env_var, raw_value, expected):
        monkeypatch.setenv(env_var, raw_value)
        cfg = fresh_config()
        actual = getattr(cfg, self._attr_for_env(env_var))
        assert actual is expected

    def test_fve_report_path_coercion(self, fresh_config, monkeypatch):
        monkeypatch.setenv("FVE_REPORT_PATH", "/tmp/custom_report.json")
        cfg = fresh_config()
        assert cfg.fve_report_path == Path("/tmp/custom_report.json")

    @staticmethod
    def _attr_for_env(env_var: str) -> str:
        mapping = {
            "QKD_SERVICE_HOST": "service_host",
            "QKD_SERVICE_PORT": "service_port",
            "QKD_LOG_LEVEL": "log_level",
            "QKD_MAX_KEYS": "max_keys",
            "QKD_ROTATION_INTERVAL": "rotation_interval",
            "QKD_KEY_TTL": "key_ttl",
            "QKD_KYBER_PUBLIC_KEY_SIZE": "kyber_public_key_size",
            "QKD_KYBER_SECRET_KEY_SIZE": "kyber_secret_key_size",
            "QKD_KYBER_CIPHERTEXT_SIZE": "kyber_ciphertext_size",
            "FVE_ENABLED": "fve_enabled",
            "FVE_REPORT_PATH": "fve_report_path",
            "FVE_STRICT_MODE": "fve_strict_mode",
        }
        return mapping[env_var]


